content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-019

=== 用户原始指令 (query.txt) ===
做个横向排几个勾选小卡片吧，最上面放一个大的电池图标和当前电量数字，下面一排三个能勾选的小方块：调低亮度、关蓝牙、关定位，最右边一个省电模式开关。颜色用那种动感渐变色，数据先用静态的就好。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "做个横向排几个勾选小卡片吧，最上面放一个大的电池图标和当前电量数字，下面一排三个能勾选的小方块：调低亮度、关蓝牙、关定位，最右边一个省电模式开关。颜色用那种动感渐变色，数据先用静态的就好。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "SetSettingSwitch",
        "params": {
          "appBundleName": "com.huawei.hmos.settings",
          "itemName": "battery_saving_mode",
          "switchFlag": 0
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "battery": {
        "title": "低电模式",
        "levelText": "18%",
        "hint": "建议开启省电",
        "checks": [
          {
            "label": "调低亮度",
            "checked": true
          },
          {
            "label": "关蓝牙",
            "checked": true
          },
          {
            "label": "关定位",
            "checked": false
          }
        ],
        "actionText": "省电模式"
      },
      "asset": {
        "batteryIcon": "resources/base/media/icon_electricity.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "battery_icon",
      "src": "resources/base/media/icon_electricity.png",
      "use": "battery icon",
      "description": "低电和电池状态语义图标，适合用于省电模式卡片的主视觉电池标识。",
      "bindTo": "/asset/batteryIcon",
      "static": true
    }
  ]
}

